        },
        "required": [
          "booth_number",
          "spm_code",
          "average_transaction_duration",
          "spm_parameter",
          "spm_passed",
          "sla_applicable",
          "sla_parameter",
          "sla_passed"
        ],
        "additionalProperties": false
      }
    }
  },
  "required": [
    "monitoring_transaction_id",
    "section_id",
    "section_name",
    "gate_id",
    "gate_name",
    "date",
    "shift",
    "evaluations"
  ],
  "additionalProperties": false
}
